267	// assertCommandMatches requires a command to appear identically in AGENTS.md
268	// and ci.yml, in every place either file states it.
269	func assertCommandMatches(t *testing.T, pattern *regexp.Regexp, name, why string) {
270		t.Helper()
271	
272		agents := readFile(t, agentsPath)
273		ci := readCI(t)
274	
275		ciMatches := pattern.FindAllString(ci, -1)
276		if len(ciMatches) == 0 {
277			t.Fatalf("could not locate the %s in %s using %s; update this pattern if the job changed", name, ciPath, pattern)
278		}
279	
280		docMatches := pattern.FindAllString(agents, -1)
281		if len(docMatches) == 0 {
282			t.Fatalf("could not locate the %s in AGENTS.md using %s — %s, so it must be documented", name, pattern, why)
283		}
284	
285		want := strings.TrimSpace(ciMatches[0])
286		for i, got := range append(ciMatches, docMatches...) {
287			if strings.TrimSpace(got) != want {
288				t.Errorf("%s occurrence %d disagrees.\n  want: %s\n  got:  %s\n%s",
289					name, i+1, want, strings.TrimSpace(got), why)
290			}
291		}
292	}
293	
294	// TestRegisteredSubagentsDeferToAgentSourceOfTruth enforces the rule at the top
295	// of AGENTS.md: subagents describe their role but defer pinned commands and
296	// versions to the source of truth, so there is only one place to update. It
297	// matches commands and version literals — mechanical strings, not prose.
298	func TestRegisteredSubagentsDeferToAgentSourceOfTruth(t *testing.T) {
299		agentFiles := []string{"ui-review.md", "verifier.md", "code-review.md"}
300	
301		// Patterns, not literals: the real commands carry version pins
302		// (`golangci-lint@v2.12.2 run`), so a bare-string check would never fire
303		// on the copy-paste it is meant to catch.
304		forbidden := []*regexp.Regexp{
305			regexp.MustCompile(`golangci-lint(@v[\d.]+)?\s+run`),
306			regexp.MustCompile(`markdownlint-cli(@[\d.]+)?\s+--config`),
307			regexp.MustCompile(`docker[ -]compose up`),
308			regexp.MustCompile(`tofu (fmt|validate)`),
309			regexp.MustCompile(`go test -race`),
310			regexp.MustCompile(`npx playwright test`),
311			// Bare version literals, including the `go1.26.5` form AGENTS.md tells
312			// agents to look for — there is no word boundary between `o` and `1`,
313			// so a `\b`-anchored pattern would miss it.
314			regexp.MustCompile(`\bgo\d+\.\d+\.\d+`),
315			regexp.MustCompile(`\bv?\d+\.\d+\.\d+\b`),
316		}
317	
318		for _, name := range agentFiles {
319			t.Run(name, func(t *testing.T) {
320				path := filepath.Join("..", ".claude", "agents", name)
321				content := readFile(t, path)
322	
323				// A real reference, not a substring: `\b` matches inside
324				// `NOT-AGENTS.md`, since `-` is already a non-word character.
325				if !regexp.MustCompile(`(^|[^\w-])AGENTS\.md($|[^\w])`).MatchString(content) {
326					t.Errorf("%s does not defer to AGENTS.md", path)
327				}
328	
329				for _, pattern := range forbidden {
330					if match := pattern.FindString(content); match != "" {
331						t.Errorf("%s inlines %q instead of deferring to AGENTS.md, which owns the pinned versions and commands", path, match)
332					}
333				}
334			})
335		}
336	}

